DBLP.sparql:
PREFIX dblp: <https://dblp.org/rdf/schema#>
SELECT ?author ?authorName WHERE {
  BIND (<https://dblp.org/rec/journals/corr/VaswaniSPUJGKP17> AS ?pub)
  ?pub dblp:authoredBy ?author .
  OPTIONAL { ?author dblp:creatorName ?authorName . }
}

PREFIX dblp: https://dblp.org/rdf/schema# 
PREFIX xsd: http://www.w3.org/2001/XMLSchema# 
SELECT DISTINCT ?coauthor WHERE { 
  BIND (https://dblp.org/pid/b/HannahBast AS ?author) 
  ?pub a dblp:Publication ; 
       dblp:authoredBy ?author ; 
       dblp:authoredBy ?coauthor ; 
       dblp:yearOfPublication ?y . 
  FILTER(?coauthor != ?author) 
  FILTER(STR(?y) > STR(YEAR(NOW()) - 7)) 
}

PREFIX dblp: <https://dblp.org/rdf/schema#>
 PREFIX cito: <http://purl.org/spar/cito/>
 PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
 SELECT ?label (?ref as ?dblp) (SAMPLE(?dois) as ?doi)  WHERE {
   VALUES ?publ { <https://dblp.org/rec/books/acm/19/0001MW19> }
   ?publ dblp:omid ?publ_omid .
   ?cite cito:hasCitingEntity ?publ_omid ; cito:hasCitedEntity ?ref_omid .
   ?ref dblp:omid ?ref_omid ; a dblp:Publication . 
   OPTIONAL {
     ?ref rdfs:label ?label .
     OPTIONAL { ?ref dblp:doi ?dois . }
   }
 }
 GROUP BY ?label ?ref
